import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { authAPI } from '../../services/api';
import { Link } from 'react-router-dom';

const Signup = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    role: 'apprenti',
    avatar: null,
    bio: '',
    phone: '',
    dateOfBirth: '',
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [avatarPreview, setAvatarPreview] = useState(null);
  
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    if (error) setError('');
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const validTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp'];
      if (!validTypes.includes(file.type)) {
        setError('Veuillez sélectionner une image valide (JPG, PNG, GIF, WebP)');
        return;
      }

      const maxSize = 5 * 1024 * 1024;
      if (file.size > maxSize) {
        setError('La taille de l\'image ne doit pas dépasser 5MB');
        return;
      }

      setFormData({
        ...formData,
        avatar: file
      });

      const reader = new FileReader();
      reader.onload = (e) => {
        setAvatarPreview(e.target.result);
      };
      reader.readAsDataURL(file);
      
      setError('');
    }
  };

  const removeAvatar = () => {
    setFormData({
      ...formData,
      avatar: null
    });
    setAvatarPreview(null);
    const fileInput = document.getElementById('avatar');
    if (fileInput) {
      fileInput.value = '';
    }
  };

  const triggerFileInput = () => {
    const fileInput = document.getElementById('avatar');
    if (fileInput) {
      fileInput.click();
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccess('');
    
    try {
      const formDataToSend = new FormData();
      
      const userPayload = {
        name: formData.name,
        email: formData.email,
        password: formData.password,
        role: formData.role,
        profile: {
          bio: formData.bio,
          phone: formData.phone,
          dateOfBirth: formData.dateOfBirth,
        }
      };

      formDataToSend.append('user', JSON.stringify(userPayload));
      
      if (formData.avatar) {
        formDataToSend.append('avatar', formData.avatar);
      }

      const response = await authAPI.signup(formDataToSend);
      
      if (response.data.success) {
        setSuccess('Compte créé avec succès ! Redirection en cours...');
        setTimeout(() => {
          navigate('/login');
        }, 2000);
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Erreur lors de la création du compte');
    } finally {
      setLoading(false);
    }
  };

  const styles = {
    authContainer: {
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '2rem 1rem',
      background: `
        linear-gradient(rgba(220, 53, 69, 0.85), rgba(168, 30, 42, 0.9)),
        url('https://images.unsplash.com/photo-1522202176988-66273c2fd55f?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=2071&q=80')
      `,
      backgroundSize: 'cover',
      backgroundPosition: 'center',
      backgroundAttachment: 'fixed',
      position: 'relative',
      overflow: 'hidden',
    },
    backgroundOverlay: {
      position: 'absolute',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      background: `
        radial-gradient(circle at 30% 20%, rgba(255, 255, 255, 0.1) 0%, transparent 50%),
        radial-gradient(circle at 70% 80%, rgba(255, 255, 255, 0.08) 0%, transparent 50%)
      `,
      animation: 'float 15s ease-in-out infinite',
    },
    card: {
      background: 'rgba(255, 255, 255, 0.98)',
      backdropFilter: 'blur(20px)',
      borderRadius: '24px',
      padding: '2.5rem 2rem',
      width: '100%',
      maxWidth: '500px',
      boxShadow: `
        0 30px 60px rgba(0, 0, 0, 0.3),
        0 0 0 1px rgba(255, 255, 255, 0.2),
        inset 0 1px 0 rgba(255, 255, 255, 0.4)
      `,
      position: 'relative',
      zIndex: 1,
      maxHeight: '90vh',
      overflowY: 'auto',
      transform: 'translateY(0)',
      transition: 'all 0.3s ease',
    },
    cardHeader: {
      textAlign: 'center',
      marginBottom: '2rem',
      paddingBottom: '1rem',
      borderBottom: '2px solid rgba(220, 53, 69, 0.1)',
    },
    cardTitle: {
      fontSize: '2rem',
      fontWeight: '700',
      background: 'linear-gradient(135deg, #dc3545, #c82333)',
      WebkitBackgroundClip: 'text',
      WebkitTextFillColor: 'transparent',
      backgroundClip: 'text',
      marginBottom: '0.5rem',
    },
    cardSubtitle: {
      color: '#6c757d',
      fontSize: '0.95rem',
      fontWeight: '400',
      margin: 0,
    },
    sectionTitle: {
      fontSize: '1rem',
      fontWeight: '600',
      color: '#374151',
      marginBottom: '1rem',
      paddingBottom: '0.5rem',
      borderBottom: '2px solid #e5e7eb',
      position: 'relative',
    },
    sectionTitleBefore: {
      content: '""',
      position: 'absolute',
      bottom: '-2px',
      left: 0,
      width: '40px',
      height: '2px',
      background: 'linear-gradient(135deg, #dc3545, #c82333)',
    },
    formSection: {
      marginBottom: '2rem',
      background: 'rgba(248, 249, 250, 0.8)',
      padding: '1.5rem',
      borderRadius: '16px',
      border: '1px solid rgba(220, 53, 69, 0.1)',
    },
    formGroup: {
      marginBottom: '1.2rem',
    },
    formLabel: {
      display: 'block',
      fontWeight: '600',
      fontSize: '0.9rem',
      color: '#374151',
      marginBottom: '0.5rem',
    },
    formControl: {
      width: '100%',
      padding: '0.8rem 1rem',
      fontSize: '0.95rem',
      border: '2px solid #e5e7eb',
      borderRadius: '10px',
      backgroundColor: '#fff',
      transition: 'all 0.3s ease',
      fontFamily: 'inherit',
      outline: 'none',
    },
    formControlFocus: {
      borderColor: '#dc3545',
      boxShadow: '0 0 0 3px rgba(220, 53, 69, 0.1)',
      transform: 'translateY(-1px)',
    },
    avatarSection: {
      textAlign: 'center',
      marginBottom: '1.5rem',
    },
    avatarContainer: {
      position: 'relative',
      display: 'inline-block',
      marginBottom: '1rem',
    },
    avatarCircle: {
      width: '100px',
      height: '100px',
      borderRadius: '50%',
      border: '3px dashed #e5e7eb',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      cursor: 'pointer',
      position: 'relative',
      overflow: 'hidden',
      backgroundColor: '#f8f9fa',
      transition: 'all 0.3s ease',
      margin: '0 auto',
    },
    avatarCircleActive: {
      borderColor: '#dc3545',
      borderStyle: 'solid',
    },
    avatarPlaceholder: {
      textAlign: 'center',
      color: '#6c757d',
    },
    avatarImage: {
      width: '100%',
      height: '100%',
      borderRadius: '50%',
      objectFit: 'cover',
      position: 'absolute',
      top: 0,
      left: 0,
    },
    avatarOverlay: {
      position: 'absolute',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      backgroundColor: 'rgba(0, 0, 0, 0.5)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      opacity: 0,
      transition: 'opacity 0.3s ease',
      borderRadius: '50%',
      color: 'white',
      fontSize: '0.75rem',
      fontWeight: '500',
    },
    removeButton: {
      position: 'absolute',
      top: '-5px',
      right: '-5px',
      background: '#dc3545',
      color: 'white',
      border: 'none',
      borderRadius: '50%',
      width: '26px',
      height: '26px',
      cursor: 'pointer',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontSize: '16px',
      boxShadow: '0 2px 8px rgba(220, 53, 69, 0.4)',
      transition: 'all 0.2s ease',
    },
    btn: {
      width: '100%',
      padding: '1rem 1.5rem',
      border: 'none',
      borderRadius: '12px',
      fontSize: '1rem',
      fontWeight: '600',
      cursor: 'pointer',
      transition: 'all 0.3s ease',
      position: 'relative',
      overflow: 'hidden',
      marginTop: '0.5rem',
    },
    btnPrimary: {
      background: 'linear-gradient(135deg, #dc3545 0%, #c82333 100%)',
      color: 'white',
      boxShadow: '0 4px 15px rgba(220, 53, 69, 0.4)',
    },
    btnDisabled: {
      background: 'linear-gradient(135deg, #6c757d 0%, #5a6268 100%)',
      cursor: 'not-allowed',
      boxShadow: '0 4px 15px rgba(108, 117, 125, 0.3)',
    },
    errorMessage: {
      background: 'linear-gradient(135deg, #f8d7da, #f5c6cb)',
      color: '#721c24',
      padding: '0.8rem 1rem',
      borderRadius: '10px',
      marginBottom: '1.5rem',
      border: '1px solid #f1aeb5',
      fontWeight: '500',
      fontSize: '0.9rem',
      animation: 'slideIn 0.3s ease',
    },
    successMessage: {
      background: 'linear-gradient(135deg, #d4edda, #c3e6cb)',
      color: '#155724',
      padding: '0.8rem 1rem',
      borderRadius: '10px',
      marginBottom: '1.5rem',
      border: '1px solid #c3e6cb',
      fontWeight: '500',
      fontSize: '0.9rem',
      animation: 'slideIn 0.3s ease',
    },
    link: {
      color: '#dc3545',
      textDecoration: 'none',
      fontWeight: '600',
      transition: 'all 0.2s ease',
      position: 'relative',
    },
    footerSection: {
      textAlign: 'center',
      paddingTop: '1.5rem',
      borderTop: '1px solid rgba(220, 53, 69, 0.1)',
      marginTop: '1rem',
    },
    spinner: {
      display: 'inline-block',
      width: '18px',
      height: '18px',
      border: '2px solid transparent',
      borderTop: '2px solid #fff',
      borderRadius: '50%',
      animation: 'spin 1s linear infinite',
      marginLeft: '8px',
    }
  };

  return (
    <>
      <style>
        {`
          @keyframes float {
            0%, 100% { transform: translate(0, 0) rotate(0deg); }
            33% { transform: translate(-10px, -10px) rotate(1deg); }
            66% { transform: translate(10px, -20px) rotate(-1deg); }
          }
          
          @keyframes slideIn {
            from {
              opacity: 0;
              transform: translateY(-10px);
            }
            to {
              opacity: 1;
              transform: translateY(0);
            }
          }
          
          @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
          }
          
          .signup-card:hover {
            transform: translateY(-3px) !important;
          }
          
          .signup-btn:hover:not(:disabled) {
            background: linear-gradient(135deg, #c82333 0%, #a71e2a 100%) !important;
            box-shadow: 0 6px 25px rgba(220, 53, 69, 0.6) !important;
            transform: translateY(-2px) !important;
          }
          
          .form-input:focus {
            border-color: #dc3545 !important;
            box-shadow: 0 0 0 3px rgba(220, 53, 69, 0.1) !important;
            transform: translateY(-1px) !important;
          }
          
          .form-input:hover {
            border-color: #d1d5db !important;
          }
          
          .avatar-overlay:hover {
            opacity: 1 !important;
          }
          
          .remove-btn:hover {
            background: #a71e2a !important;
            transform: scale(1.1) !important;
          }
          
          .signup-link:hover {
            color: #c82333 !important;
          }
          
          .signup-link::after {
            content: '';
            position: absolute;
            bottom: -2px;
            left: 0;
            width: 0;
            height: 2px;
            background: linear-gradient(135deg, #dc3545, #c82333);
            transition: width 0.3s ease;
          }
          
          .signup-link:hover::after {
            width: 100%;
          }
          
          .card::-webkit-scrollbar {
            width: 6px;
          }
          
          .card::-webkit-scrollbar-track {
            background: rgba(0,0,0,0.1);
            border-radius: 3px;
          }
          
          .card::-webkit-scrollbar-thumb {
            background: rgba(220, 53, 69, 0.3);
            border-radius: 3px;
          }
          
          .card::-webkit-scrollbar-thumb:hover {
            background: rgba(220, 53, 69, 0.5);
          }
          
          @media (max-width: 768px) {
            .auth-container {
              padding: 1rem 0.5rem !important;
            }
            
            .card {
              padding: 2rem 1.5rem !important;
              margin: 0.5rem !important;
              border-radius: 20px !important;
              max-height: 95vh !important;
            }
            
            .card-title {
              font-size: 1.7rem !important;
            }
            
            .form-section {
              padding: 1rem !important;
            }
          }
        `}
      </style>
      
      <div style={styles.authContainer}>
        <div style={styles.backgroundOverlay}></div>
        
        <div style={styles.card} className="signup-card card">
          <div style={styles.cardHeader}>
            <h2 style={styles.cardTitle}>Créer un compte</h2>
            <p style={styles.cardSubtitle}>
              Rejoignez Tunisair Academy dès aujourd'hui
            </p>
          </div>
          
          <form onSubmit={handleSubmit}>
            {error && (
              <div style={styles.errorMessage}>
                {error}
              </div>
            )}
            
            {success && (
              <div style={styles.successMessage}>
                {success}
              </div>
            )}

            {/* Informations de base */}
            <div style={styles.formSection}>
              <h4 style={styles.sectionTitle}>
                Informations de base
                <span style={styles.sectionTitleBefore}></span>
              </h4>

              <div style={styles.formGroup}>
                <label htmlFor="name" style={styles.formLabel}>Nom complet *</label>
                <input
                  type="text"
                  id="name"
                  name="name"
                  style={styles.formControl}
                  className="form-input"
                  value={formData.name}
                  onChange={handleChange}
                  required
                  placeholder="Votre nom complet"
                />
              </div>

              <div style={styles.formGroup}>
                <label htmlFor="email" style={styles.formLabel}>Email *</label>
                <input
                  type="email"
                  id="email"
                  name="email"
                  style={styles.formControl}
                  className="form-input"
                  value={formData.email}
                  onChange={handleChange}
                  required
                  placeholder="votre.email@exemple.com"
                />
              </div>

              <div style={styles.formGroup}>
                <label htmlFor="password" style={styles.formLabel}>Mot de passe *</label>
                <input
                  type="password"
                  id="password"
                  name="password"
                  style={styles.formControl}
                  className="form-input"
                  value={formData.password}
                  onChange={handleChange}
                  required
                  placeholder="Minimum 6 caractères"
                  minLength="6"
                />
              </div>

              <div style={styles.formGroup}>
                <label htmlFor="role" style={styles.formLabel}>Rôle *</label>
                <select
                  id="role"
                  name="role"
                  style={styles.formControl}
                  className="form-input"
                  value={formData.role}
                  onChange={handleChange}
                  required
                >
                  <option value="apprenti">Apprenti</option>
                  <option value="tuteur">Tuteur</option>
                </select>
              </div>
            </div>

            {/* Avatar */}
            <div style={styles.formSection}>
              <h4 style={styles.sectionTitle}>
                Photo de profil
                <span style={styles.sectionTitleBefore}></span>
              </h4>
              
              <div style={styles.avatarSection}>
                <div style={styles.avatarContainer}>
                  <div 
                    onClick={triggerFileInput}
                    style={{
                      ...styles.avatarCircle,
                      ...(avatarPreview ? styles.avatarCircleActive : {})
                    }}
                  >
                    {!avatarPreview && (
                      <div style={styles.avatarPlaceholder}>
                        <div style={{ fontSize: '1.5rem', marginBottom: '0.25rem' }}>📷</div>
                        <div style={{ fontSize: '0.75rem', fontWeight: '500' }}>
                          Ajouter
                        </div>
                      </div>
                    )}
                    
                    {avatarPreview && (
                      <img 
                        src={avatarPreview} 
                        alt="Avatar" 
                        style={styles.avatarImage}
                      />
                    )}
                    
                    {avatarPreview && (
                      <div style={styles.avatarOverlay} className="avatar-overlay">
                        Changer
                      </div>
                    )}
                  </div>

                  {avatarPreview && (
                    <button 
                      type="button" 
                      onClick={(e) => {
                        e.stopPropagation();
                        removeAvatar();
                      }}
                      style={styles.removeButton}
                      className="remove-btn"
                      title="Supprimer la photo"
                    >
                      ×
                    </button>
                  )}
                </div>

                <input
                  type="file"
                  id="avatar"
                  name="avatar"
                  accept="image/*"
                  onChange={handleFileChange}
                  style={{ display: 'none' }}
                />
                
                <div style={{ marginBottom: '0.5rem' }}>
                  <small style={{ color: '#6c757d', fontSize: '0.8rem' }}>
                    Formats acceptés : JPG, PNG, GIF, WebP (max 5MB)
                  </small>
                </div>

                {avatarPreview && (
                  <div style={{ 
                    backgroundColor: 'rgba(220, 53, 69, 0.1)', 
                    padding: '0.5rem 0.8rem', 
                    borderRadius: '8px',
                    fontSize: '0.8rem',
                    color: '#374151',
                    border: '1px solid rgba(220, 53, 69, 0.2)'
                  }}>
                    <strong>Fichier :</strong> {formData.avatar.name} 
                    ({(formData.avatar.size / 1024 / 1024).toFixed(2)} MB)
                  </div>
                )}
              </div>
            </div>

            {/* Informations personnelles */}
            <div style={styles.formSection}>
              <h4 style={styles.sectionTitle}>
                Informations personnelles (optionnel)
                <span style={styles.sectionTitleBefore}></span>
              </h4>

              <div style={styles.formGroup}>
                <label htmlFor="bio" style={styles.formLabel}>Bio</label>
                <textarea
                  id="bio"
                  name="bio"
                  style={{...styles.formControl, resize: 'vertical', minHeight: '80px'}}
                  className="form-input"
                  value={formData.bio}
                  onChange={handleChange}
                  placeholder="Décrivez-vous en quelques mots..."
                  rows="3"
                />
              </div>

              <div style={styles.formGroup}>
                <label htmlFor="phone" style={styles.formLabel}>Téléphone</label>
                <input
                  type="tel"
                  id="phone"
                  name="phone"
                  style={styles.formControl}
                  className="form-input"
                  value={formData.phone}
                  onChange={handleChange}
                  placeholder="+33 1 23 45 67 89"
                />
              </div>

              <div style={styles.formGroup}>
                <label htmlFor="dateOfBirth" style={styles.formLabel}>Date de naissance</label>
                <input
                  type="date"
                  id="dateOfBirth"
                  name="dateOfBirth"
                  style={styles.formControl}
                  className="form-input"
                  value={formData.dateOfBirth}
                  onChange={handleChange}
                />
              </div>
            </div>
            
            <button
              type="submit"
              style={{
                ...styles.btn,
                ...(loading ? styles.btnDisabled : styles.btnPrimary)
              }}
              className="signup-btn"
              disabled={loading}
            >
              {loading ? (
                <>
                  Création du compte...
                  <span style={styles.spinner}></span>
                </>
              ) : 'Créer mon compte'}
            </button>
          </form>
          
          <div style={styles.footerSection}>
            <p style={{ color: '#6c757d', fontSize: '0.9rem', margin: 0 }}>
              Déjà un compte ?{' '}
              <Link to="/login" style={styles.link} className="signup-link">
                Connectez-vous ici
              </Link>
            </p>
          </div>
        </div>
      </div>
    </>
  );
};

export default Signup;
